<?php
declare(strict_types=1);require_once dirname(__DIR__).'/config/bootstrap.php';require_permission('inventory.adjust');$productDefault=(int)($_GET['product']??0);$products=db()->query('SELECT p.id,p.name,p.sku,p.current_stock,u.short_name,u.allows_decimal FROM products p INNER JOIN units u ON u.id=p.unit_id WHERE p.status="active" AND p.track_stock=1 ORDER BY p.name')->fetchAll();$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){require_valid_csrf();$productId=(int)($_POST['product_id']??0);$direction=(string)($_POST['direction']??'');$reasonType=(string)($_POST['reason_type']??'');$reason=trim((string)($_POST['reason']??''));try{$qty=quantity_to_milli((string)($_POST['quantity']??'0'));if($qty<=0)throw new InvalidArgumentException();}catch(Throwable){$errors[]='Enter a quantity greater than zero.';$qty=0;}$validReasons=['adjustment','damage','loss'];if(!in_array($reasonType,$validReasons,true))$errors[]='Choose an adjustment reason.';if(!in_array($direction,['in','out'],true))$errors[]='Choose stock in or stock out.';if($reason==='')$errors[]='Explain why this stock adjustment is required.';
$pr=db()->prepare('SELECT p.*,u.short_name,u.allows_decimal FROM products p INNER JOIN units u ON u.id=p.unit_id WHERE p.id=:id AND p.track_stock=1');$pr->execute([':id'=>$productId]);$product=$pr->fetch();if(!$product)$errors[]='Choose a valid stock-tracked product.';elseif((int)$product['allows_decimal']===0&&$qty%1000!==0)$errors[]='This product accepts whole quantities only.';
if(!$errors){$pdo=db();try{$pdo->beginTransaction();$lock=$pdo->prepare('SELECT current_stock,average_cost FROM products WHERE id=:id FOR UPDATE');$lock->execute([':id'=>$productId]);$fresh=$lock->fetch();$before=quantity_to_milli($fresh['current_stock']);$change=$direction==='in'?$qty:-$qty;$after=$before+$change;if($after<0&&!allow_negative_stock())throw new RuntimeException('This adjustment would make stock negative.');$movementType=$reasonType==='damage'?'damage':($reasonType==='loss'?'loss':($direction==='in'?'adjustment_in':'adjustment_out'));if(in_array($reasonType,['damage','loss'],true)&&$direction!=='out')throw new RuntimeException('Damage and loss must reduce stock.');$up=$pdo->prepare('UPDATE products SET current_stock=:stock WHERE id=:id');$up->execute([':stock'=>milli_to_decimal($after),':id'=>$productId]);$ref='ADJ-'.date('Ymd-His').'-'.$productId;$sm=$pdo->prepare('INSERT INTO stock_movements(branch_id,product_id,movement_type,reference_type,reference_id,reference_no,quantity_change,unit_cost,stock_before,stock_after,reason,created_by) VALUES(:branch,:product,:type,"adjustment",NULL,:ref,:change,:cost,:before,:after,:reason,:user)');$sm->execute([':branch'=>current_branch_id(),':product'=>$productId,':type'=>$movementType,':ref'=>$ref,':change'=>milli_to_decimal($change),':cost'=>$fresh['average_cost'],':before'=>milli_to_decimal($before),':after'=>milli_to_decimal($after),':reason'=>$reason,':user'=>(int)current_user()['id']]);$movementId=(int)$pdo->lastInsertId();$pdo->commit();audit_log('stock_adjusted','inventory',$movementId,'Stock adjusted for '.$product['name'].'.',['stock'=>milli_to_decimal($before)],['stock'=>milli_to_decimal($after),'reason'=>$reason]);flash('success','Stock adjustment saved.');redirect('products/view?id='.$productId);}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();$errors[]=$e->getMessage();}}
}
$pageTitle='Stock Adjustment';$pageStyles=['admin.css','commerce.css'];require BASE_PATH.'/includes/header.php';require BASE_PATH.'/includes/sidebar.php';?>
<div class="app-main"><?php require BASE_PATH.'/includes/navbar.php';?><main class="content"><div class="narrow-page"><div class="page-toolbar"><div><a class="back-link" href="<?=e(app_url('inventory/index'))?>">← Inventory</a><h2>Stock adjustment</h2><p>Every adjustment creates a permanent stock movement and audit entry.</p></div></div><?php foreach($errors as$e1):?><div class="app-alert app-alert--danger"><?=e($e1)?></div><?php endforeach;?><form method="post" class="form-card"><?=csrf_field()?><div class="form-section"><div class="form-grid"><div class="field field--span-2"><label>Product</label><select name="product_id" required><option value="">Select product</option><?php foreach($products as$p):?><option value="<?=e((string)$p['id'])?>" <?=$productDefault===(int)$p['id']?'selected':''?>><?=e($p['name'])?> · <?=e(format_quantity($p['current_stock']))?> <?=e($p['short_name'])?></option><?php endforeach;?></select></div><div class="field"><label>Direction</label><select name="direction" required><option value="in">Stock in (+)</option><option value="out">Stock out (−)</option></select></div><div class="field"><label>Quantity</label><input type="number" name="quantity" min="0.001" step="0.001" required></div><div class="field field--span-2"><label>Reason type</label><select name="reason_type" required><option value="adjustment">Stock correction / adjustment</option><option value="damage">Damaged stock</option><option value="loss">Lost stock</option></select></div><div class="field field--span-2"><label>Explanation</label><textarea name="reason" rows="4" required placeholder="Why is this adjustment being made?"></textarea></div></div></div><div class="form-actions"><a class="button button--ghost" href="<?=e(app_url('inventory/index'))?>">Cancel</a><button class="button button--primary">Save adjustment</button></div></form></div></main></div><?php require BASE_PATH.'/includes/footer.php';?>
